"""
base.py — shared base class and UI helper factories for all wizard screens.

Every screen subclasses BasePage (an Adw.NavigationPage) and gets:
  - self.state  — shared WizardState
  - self.go_to  — navigation callback
  - Helper methods for common widgets (header, button row, info banners)
"""

import gi
gi.require_version("Gtk", "4.0")
gi.require_version("Adw", "1")

from gi.repository import Gtk, Adw
from typing import Callable

from ..state import WizardState


class BasePage(Adw.NavigationPage):
    """
    Base class for all wizard screens.

    Subclasses must call super().__init__(state, go_to, title, tag)
    and implement build_content() which returns the main Gtk.Widget.
    """

    def __init__(
        self,
        state: WizardState,
        go_to: Callable[[str], None],
        title: str,
        tag: str,
    ):
        super().__init__(title=title, tag=tag)
        self.state = state
        self.go_to = go_to

        # Outer scrollable content area inside a ToolbarView
        self._toolbar_view = Adw.ToolbarView()
        self.set_child(self._toolbar_view)

        # Header bar
        header = Adw.HeaderBar()
        header.set_show_end_title_buttons(False)
        header.set_show_back_button(True)
        self._toolbar_view.add_top_bar(header)

        # Clamp + scroll for the body
        self._clamp = Adw.Clamp()
        self._clamp.set_maximum_size(620)
        self._clamp.set_margin_top(24)
        self._clamp.set_margin_bottom(24)
        self._clamp.set_margin_start(24)
        self._clamp.set_margin_end(24)

        scroll = Gtk.ScrolledWindow()
        scroll.set_policy(Gtk.PolicyType.NEVER, Gtk.PolicyType.AUTOMATIC)
        scroll.set_vexpand(True)
        scroll.set_child(self._clamp)

        self._toolbar_view.set_content(scroll)

        # Body box — subclasses append widgets here
        self._body = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=16)
        self._clamp.set_child(self._body)

        self._build()

    def _build(self):
        """Override in subclasses to populate self._body."""
        pass

    def on_enter(self):
        """
        Called by WizardWindow just before this screen is pushed.
        Override to refresh dynamic content (e.g. re-render the review page).
        """
        pass

    # ------------------------------------------------------------------
    # Widget factory helpers
    # ------------------------------------------------------------------

    @staticmethod
    def make_page_header(title: str, subtitle: str) -> Gtk.Widget:
        """Large title + subtitle block at the top of a screen body."""
        box = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=6)
        box.set_margin_bottom(8)

        lbl_title = Gtk.Label(label=title)
        lbl_title.set_xalign(0)
        lbl_title.set_wrap(True)
        lbl_title.add_css_class("title-1")
        box.append(lbl_title)

        lbl_sub = Gtk.Label(label=subtitle)
        lbl_sub.set_xalign(0)
        lbl_sub.set_wrap(True)
        lbl_sub.add_css_class("body")
        lbl_sub.get_style_context().add_class("dim-label")
        box.append(lbl_sub)

        return box

    @staticmethod
    def make_banner(text: str, style: str = "warning") -> Adw.Banner:
        """
        Inline info/warning/error banner.
        style: 'warning' | 'error' | 'success' (maps to Adw.Banner + CSS)
        """
        banner = Adw.Banner()
        banner.set_title(text)
        banner.set_revealed(True)
        return banner

    @staticmethod
    def make_button_row(
        back_label: str | None,
        back_cb,
        next_label: str,
        next_cb,
        next_style: str = "suggested-action",
    ) -> Gtk.Widget:
        """
        Standard bottom button row: [back] ... [next]
        Pass back_label=None to hide the back button.
        """
        row = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=12)
        row.set_margin_top(8)

        if back_label:
            btn_back = Gtk.Button(label=back_label)
            btn_back.connect("clicked", lambda _: back_cb())
            row.append(btn_back)

        spacer = Gtk.Box()
        spacer.set_hexpand(True)
        row.append(spacer)

        btn_next = Gtk.Button(label=next_label)
        btn_next.add_css_class(next_style)
        btn_next.connect("clicked", lambda _: next_cb())
        row.append(btn_next)

        return row

    @staticmethod
    def make_status_row(label: str, value: str, value_css: str = "") -> Gtk.Widget:
        """
        A single labelled status row (label ... value), used in detection/review screens.
        """
        row = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=8)

        lbl = Gtk.Label(label=label)
        lbl.set_xalign(0)
        lbl.add_css_class("dim-label")
        lbl.set_hexpand(True)
        row.append(lbl)

        val = Gtk.Label(label=value)
        val.set_xalign(1)
        if value_css:
            val.add_css_class(value_css)
        row.append(val)

        return row

    @staticmethod
    def make_group(title: str, widgets: list) -> Adw.PreferencesGroup:
        """Wraps a list of Gtk widgets in an Adw.PreferencesGroup."""
        group = Adw.PreferencesGroup()
        group.set_title(title)
        for w in widgets:
            group.add(w)
        return group
